import { useEffect, useRef, useState } from 'react'

export type ContainerSize = {
  width: number
  height: number
}

/**
 * Observe a container’s size. Prefer this over window resize for components.
 * The observer is disconnected on unmount.
 */
export function useContainerSize<T extends HTMLElement = HTMLDivElement>() {
  const ref = useRef<T | null>(null)
  const [size, setSize] = useState<ContainerSize>({ width: 0, height: 0 })

  useEffect(() => {
    const node = ref.current
    if (!node) return

    const measure = () => {
      const rect = node.getBoundingClientRect()
      setSize((prev) =>
        prev.width === rect.width && prev.height === rect.height
          ? prev
          : { width: rect.width, height: rect.height },
      )
    }

    // Measure once immediately. ResizeObserver is not guaranteed to deliver an
    // initial entry in every embedded browser, and charts need a width to draw.
    measure()

    const observer =
      typeof ResizeObserver === 'undefined'
        ? null
        : new ResizeObserver((entries) => {
            const entry = entries[0]
            if (!entry) return
            const box = entry.contentRect
            setSize((prev) =>
              prev.width === box.width && prev.height === box.height
                ? prev
                : { width: box.width, height: box.height },
            )
          })

    observer?.observe(node)
    window.addEventListener('resize', measure)

    return () => {
      observer?.disconnect()
      window.removeEventListener('resize', measure)
    }
  }, [])

  return { ref, ...size }
}

/** Container-query helper: true when the observed width is at least `px`. */
export function useContainerQuery(px: number) {
  const { ref, width } = useContainerSize()
  return { ref, width, matches: width >= px }
}

import { useCallback, useEffect, useRef, useState } from 'react'

/**
 * Supports both controlled and uncontrolled usage.
 * Controlled: pass `value` + `onValueChange`.
 * Uncontrolled: pass `defaultValue`.
 */
export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
}) {
  const [internal, setInternal] = useState<T>(defaultValue)
  const isControlled = value !== undefined
  const current = isControlled ? value : internal
  const onChangeRef = useRef(onChange)
  useEffect(() => {
    onChangeRef.current = onChange
  }, [onChange])

  const setValue = useCallback(
    (next: T | ((prev: T) => T)) => {
      const resolved =
        typeof next === 'function'
          ? (next as (prev: T) => T)(current)
          : next
      if (!isControlled) setInternal(resolved)
      onChangeRef.current?.(resolved)
    },
    [current, isControlled],
  )

  return [current, setValue] as const
}

import { useCallback, useEffect, useRef, useState } from 'react'

export type CopyState = 'idle' | 'copied' | 'error'

/**
 * Clipboard copy with a self-clearing status and no leaked timers.
 * Requires a user gesture; never copy secrets automatically.
 */
export function useCopyToClipboard(resetAfterMs = 1800) {
  const [state, setState] = useState<CopyState>('idle')
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null)

  const clearTimer = useCallback(() => {
    if (timer.current) {
      clearTimeout(timer.current)
      timer.current = null
    }
  }, [])

  useEffect(() => clearTimer, [clearTimer])

  const copy = useCallback(
    async (value: string) => {
      clearTimer()
      try {
        if (!navigator.clipboard?.writeText) throw new Error('unsupported')
        await navigator.clipboard.writeText(value)
        setState('copied')
      } catch {
        setState('error')
      }
      timer.current = setTimeout(() => {
        setState('idle')
        timer.current = null
      }, resetAfterMs)
    },
    [clearTimer, resetAfterMs],
  )

  return { state, copy, reset: () => setState('idle') }
}

import { useEffect, useRef } from 'react'

export type Hotkey = {
  key: string
  meta?: boolean
  ctrl?: boolean
  alt?: boolean
  shift?: boolean
}

function isEditable(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false
  return (
    target.isContentEditable ||
    ['INPUT', 'TEXTAREA', 'SELECT'].includes(target.tagName)
  )
}

/**
 * Global hotkeys. Ignores editable targets unless `allowInInputs`.
 * Listener is removed on unmount.
 */
export function useHotkeys(
  hotkeys: Array<Hotkey & { handler: (event: KeyboardEvent) => void }>,
  options: { allowInInputs?: boolean; enabled?: boolean } = {},
) {
  const ref = useRef(hotkeys)
  useEffect(() => {
    ref.current = hotkeys
  }, [hotkeys])

  useEffect(() => {
    if (options.enabled === false) return
    const onKeyDown = (event: KeyboardEvent) => {
      if (!options.allowInInputs && isEditable(event.target)) return
      for (const hotkey of ref.current) {
        if (event.key.toLowerCase() !== hotkey.key.toLowerCase()) continue
        if (!!hotkey.meta !== event.metaKey) continue
        if (!!hotkey.ctrl !== event.ctrlKey) continue
        if (!!hotkey.alt !== event.altKey) continue
        if (!!hotkey.shift !== event.shiftKey) continue
        event.preventDefault()
        hotkey.handler(event)
        break
      }
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [options.allowInInputs, options.enabled])
}

import { useEffect, useLayoutEffect } from 'react'

/** useLayoutEffect on the client, useEffect on the server. */
export const useIsomorphicLayoutEffect =
  typeof window !== 'undefined' ? useLayoutEffect : useEffect

import { useEffect, useRef } from 'react'

/** Keep the latest value in a ref without touching it during render. */
export function useLatest<T>(value: T) {
  const ref = useRef(value)
  useEffect(() => {
    ref.current = value
  }, [value])
  return ref
}

import { useCallback, useSyncExternalStore } from 'react'

/**
 * SSR-safe media query hook.
 *
 * The server snapshot is false, so the first render matches the mobile/expanded
 * layout. On the client the subscription is removed on unmount.
 */
export function useMediaQuery(query: string): boolean {
  const subscribe = useCallback(
    (onStoreChange: () => void) => {
      const media = window.matchMedia(query)
      media.addEventListener('change', onStoreChange)
      return () => media.removeEventListener('change', onStoreChange)
    },
    [query],
  )

  const getSnapshot = useCallback(() => window.matchMedia(query).matches, [query])
  const getServerSnapshot = useCallback(() => false, [])

  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot)
}

import { useSyncExternalStore } from 'react'

const subscribe = () => () => {}

/**
 * `false` during SSR/hydration, `true` on the client.
 * Replaces the `useEffect(() => setMounted(true), [])` pattern.
 */
export function useMounted() {
  return useSyncExternalStore(
    subscribe,
    () => true,
    () => false,
  )
}

import { useSyncExternalStore } from 'react'

function subscribe(onChange: () => void) {
  if (typeof window === 'undefined') return () => {}
  window.addEventListener('online', onChange)
  window.addEventListener('offline', onChange)
  return () => {
    window.removeEventListener('online', onChange)
    window.removeEventListener('offline', onChange)
  }
}

function getSnapshot() {
  if (typeof navigator === 'undefined') return true
  return navigator.onLine
}

/** True when the browser reports a network connection. */
export function useOnlineStatus(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, () => true)
}

import { useSyncExternalStore } from 'react'

const QUERY = '(prefers-reduced-motion: reduce)'

function subscribe(onChange: () => void) {
  if (typeof window === 'undefined') return () => {}
  const mql = window.matchMedia(QUERY)
  mql.addEventListener('change', onChange)
  return () => mql.removeEventListener('change', onChange)
}

function getSnapshot() {
  if (typeof window === 'undefined') return false
  return window.matchMedia(QUERY).matches
}

/** True when the user asks for reduced motion. SSR-safe. */
export function useReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, () => false)
}
